//! The High-Precision Timestamp system contract.
//!
//! A thin wrapper that reads a microsecond-resolution timestamp out of the Oracle's storage.
//! It runs its own bytecode: no method of it is intercepted, so a call to it is an ordinary
//! call. The Oracle's address is baked into the code, which is why the code is carried here
//! rather than built from the `mega-system-contracts` sources.

use alloy_primitives::{address, b256, bytes, Address, Bytes, B256};

/// The address of the High-Precision Timestamp system contract.
pub const HIGH_PRECISION_TIMESTAMP_ORACLE_ADDRESS: Address =
    address!("0x6342000000000000000000000000000000000002");

/// The code hash of the High-Precision Timestamp contract.
pub const HIGH_PRECISION_TIMESTAMP_ORACLE_CODE_HASH: B256 =
    b256!("0x1b2df8ca5350cd7106d67ed95532584526f97a5ca267c8eef73a1831f53720f2");

/// The code of the High-Precision Timestamp contract, with the Oracle's address embedded.
pub const HIGH_PRECISION_TIMESTAMP_ORACLE_CODE: Bytes = bytes!("");
